:root {
  --bg: #071018; --panel: #0c1a26; --panel2: #0e2130; --line: #1d3a4d;
  --ink: #dcefe4; --muted: #8fb0a2; --faint: #5f7f71;
  --green: #3dff9e; --green-dim: #1d7a52; --amber: #ffc44d; --red: #ff7a6b;
  --blue: #6fc3ff; --mono: ui-monospace, "SF Mono", "Cascadia Mono", Consolas, monospace;
}
* { box-sizing: border-box; }
body {
  margin: 0; background: var(--bg); color: var(--ink);
  font: 15px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}
h1, h2, h3 { line-height: 1.2; margin: 0; }
h2 { font-size: 21px; letter-spacing: .2px; }
p { margin: 0; }
a { color: var(--green); }

/* --- masthead + radar motif --- */
.masthead {
  display: flex; gap: 28px; align-items: center;
  padding: 22px 28px 18px; border-bottom: 1px solid var(--line);
  background: radial-gradient(720px 300px at 12% 0%, #0e2a1e 0%, var(--bg) 62%);
}
.radar-ring {
  position: relative; flex: 0 0 auto; width: 148px; height: 148px; border-radius: 50%;
  border: 2px solid var(--green-dim);
  background:
    radial-gradient(circle, transparent 31%, var(--line) 32%, transparent 33%),
    radial-gradient(circle, transparent 63%, var(--line) 64%, transparent 65%);
  overflow: hidden;
}
.radar-ring::before, .radar-ring::after {
  content: ""; position: absolute; inset: 0; border-radius: 50%;
}
.radar-ring::before { background: linear-gradient(var(--line) 1px, transparent 1px) center/100% 50% no-repeat; }
.radar-ring::after { background: linear-gradient(90deg, var(--line) 1px, transparent 1px) center/50% 100% no-repeat; }
.sweep {
  position: absolute; inset: 0; border-radius: 50%;
  background: conic-gradient(from 0deg, rgba(61,255,158,.45), transparent 22%);
}
.blip { position: absolute; width: 9px; height: 9px; border-radius: 50%; background: var(--green);
  box-shadow: 0 0 10px 2px rgba(61,255,158,.7); }
.b1 { top: 30%; left: 62%; } .b2 { top: 62%; left: 30%; } .b3 { top: 44%; left: 44%; width: 7px; height: 7px; }
.kicker { color: var(--green); font: 700 12px/1.4 var(--mono); letter-spacing: 2.5px; margin-bottom: 8px; }
.mast-text h1 { font-size: 30px; letter-spacing: -.5px; }
.lede { margin-top: 8px; max-width: 780px; color: var(--muted); font-size: 16px; }
.lede strong { color: var(--green); }
.meta { margin-top: 10px; font: 12.5px var(--mono); color: var(--faint); }

/* --- stat strip --- */
.stats {
  display: grid; grid-template-columns: repeat(5, 1fr); gap: 1px;
  background: var(--line); border-bottom: 1px solid var(--line);
}
.stat { background: var(--panel); padding: 16px 20px; }
.stat b { display: block; font: 700 24px/1.2 var(--mono); color: var(--green); white-space: nowrap; }
.stat span { font-size: 12.5px; color: var(--muted); }

/* --- sections --- */
section { padding: 26px 28px; }
.section-head { margin-bottom: 16px; max-width: 900px; }
.section-head p { color: var(--muted); margin-top: 6px; font-size: 14px; }
.week { background: #08131c; border-bottom: 1px solid var(--line); }
.week-cards { display: grid; grid-template-columns: repeat(5, 1fr); gap: 12px; }
.week-card {
  background: var(--panel2); border: 1px solid var(--line); border-radius: 10px;
  padding: 14px 14px 12px; cursor: pointer;
}
.week-card:hover { border-color: var(--green-dim); }
.week-card .wk-rank { font: 700 11px var(--mono); color: var(--green); letter-spacing: 1.5px; }
.week-card h3 { font-size: 16px; margin: 5px 0 2px; }
.week-card .wk-cat { font-size: 12px; color: var(--faint); }
.week-card .wk-val { font: 700 19px/1.3 var(--mono); color: var(--ink); margin-top: 8px; }
.week-card .wk-prob { font: 12px var(--mono); color: var(--muted); margin-top: 2px; }
.week-card .wk-step { font-size: 12.5px; color: var(--muted); margin-top: 8px;
  border-top: 1px dashed var(--line); padding-top: 8px; }

/* --- controls + table --- */
.controls { display: flex; flex-wrap: wrap; gap: 14px; margin-bottom: 14px; }
.controls label { font-size: 12.5px; color: var(--muted); display: flex; flex-direction: column; gap: 4px; }
.controls input, .controls select {
  background: var(--panel); color: var(--ink); border: 1px solid var(--line);
  border-radius: 6px; padding: 7px 10px; font: 14px system-ui, sans-serif; min-width: 170px;
}
.controls input:focus, .controls select:focus { outline: 2px solid var(--green-dim); }
.table-wrap { overflow-x: auto; border: 1px solid var(--line); border-radius: 10px; }
table { width: 100%; border-collapse: collapse; background: var(--panel); font-size: 14px; }
th, td { padding: 9px 12px; text-align: left; border-bottom: 1px solid #122636; }
thead th { font: 700 11.5px var(--mono); letter-spacing: 1px; color: var(--muted);
  text-transform: uppercase; background: var(--panel2); position: sticky; top: 0; }
tbody tr { cursor: pointer; }
tbody tr:hover, tbody tr.selected { background: #10303f; }
td.num, th.num { text-align: right; font-family: var(--mono); font-size: 13.5px; white-space: nowrap; }
td .slug { color: var(--faint); font: 12px var(--mono); display: block; }
td .cat { color: var(--faint); font-size: 12px; }
.verdict { display: inline-block; font: 700 11px var(--mono); letter-spacing: .8px;
  padding: 3px 8px; border-radius: 20px; white-space: nowrap; }
.v-farm-now { background: #0d3a24; color: var(--green); border: 1px solid var(--green-dim); }
.v-farm { background: #12283a; color: var(--blue); border: 1px solid #2b5a78; }
.v-watch { background: #33290e; color: var(--amber); border: 1px solid #6b5518; }
.v-pass { background: #2a1210; color: var(--red); border: 1px solid #5c2a22; }
.count-line { margin-top: 10px; font: 12.5px var(--mono); color: var(--faint); }

/* --- detail --- */
.detail { background: #08131c; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.detail-grid { display: grid; grid-template-columns: 1fr 1.15fr; gap: 22px; }
.detail-model { background: var(--panel); border: 1px solid var(--line); border-radius: 10px; padding: 18px; }
.factor { margin-bottom: 14px; }
.factor .f-top { display: flex; justify-content: space-between; font-size: 13px; }
.factor .f-top b { font-family: var(--mono); }
.factor .f-note { font-size: 12.5px; color: var(--muted); margin-top: 2px; }
.bar { height: 8px; background: #122636; border-radius: 4px; margin-top: 6px; overflow: hidden; }
.bar i { display: block; height: 100%; background: var(--green); border-radius: 4px; }
.detail-plan h3 { margin-bottom: 10px; }
.detail-plan ol { margin: 0; padding-left: 20px; }
.detail-plan li { margin-bottom: 10px; font-size: 14.5px; }
.detail-plan li::marker { color: var(--green); font-weight: 700; }
.cost-line { margin-top: 12px; font: 13px var(--mono); color: var(--amber); }

/* --- methodology --- */
.formula {
  font: 700 17px var(--mono); color: var(--green); background: var(--panel);
  border: 1px solid var(--line); border-radius: 8px; padding: 14px 16px; margin-bottom: 18px;
  overflow-x: auto; white-space: nowrap;
}
.method-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.method-card { background: var(--panel); border: 1px solid var(--line); border-radius: 10px; padding: 14px 16px; }
.method-card h3 { font: 700 12px var(--mono); letter-spacing: 1.2px; color: var(--green); text-transform: uppercase; margin-bottom: 6px; }
.method-card p { font-size: 13.5px; color: var(--muted); }
.method-card .big { font: 700 22px var(--mono); color: var(--ink); margin: 4px 0; }
.fineprint { margin-top: 16px; font-size: 13px; color: var(--faint); max-width: 900px; }

footer { padding: 20px 28px 28px; color: var(--faint); font-size: 12.5px; }
footer p { max-width: 900px; }
.error { color: var(--red); font: 14px var(--mono); padding: 20px 28px; }

@media (max-width: 900px) {
  .masthead { flex-direction: column; align-items: flex-start; }
  .stats { grid-template-columns: repeat(2, 1fr); }
  .week-cards, .method-grid { grid-template-columns: 1fr 1fr; }
  .detail-grid { grid-template-columns: 1fr; }
  section { padding: 20px 16px; }
}
